from collections import deque

def run_stack_via_queue(operations):
    # Simulate a stack backed by a single queue; return pop results (-1 when empty).
    queue = deque()
    results = []
    for op in operations:
        if op[0] == "push":
            queue.append(op[1])
        else:
            if not queue:
                results.append(-1)
                continue
            for _ in range(len(queue) - 1):
                queue.append(queue.popleft())
            results.append(queue.popleft())
    return results

