#include <bits/stdc++.h>
using namespace std;

class QueueStack {
private:
    queue<int> q;
public:
    void push(int x) { q.push(x); }
    int pop() {
        if (q.empty()) return -1;
        for (int i = 0; i < (int)q.size() - 1; ++i) {
            q.push(q.front());
            q.pop();
        }
        int val = q.front();
        q.pop();
        return val;
    }
};

